import{_ as o,o as i,c as t,a0 as a}from"./chunks/framework.C0WKPwzJ.js";const u=JSON.parse('{"title":"Configure an instance","description":"Bind GitHub Projects, people, mail, and policies in the consumer repository — not inside the Autodevelop plugin.","frontmatter":{"title":"Configure an instance","description":"Bind GitHub Projects, people, mail, and policies in the consumer repository — not inside the Autodevelop plugin."},"headers":[],"relativePath":"configure.md","filePath":"configure.md","lastUpdated":1788171427000}'),d={name:"configure.md"};function n(c,e,s,l,r,p){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to &quot;Configure&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>Instance data stays in the <strong>consumer</strong> product repo. Pick a folder name that is not <code>autodevelop</code> or <code>third-party</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.cursor/skills/&lt;instance&gt;/autodevelop/config.json</span></span>
<span class="line"><span>.cursor/skills/&lt;instance&gt;/autodevelop/people.json</span></span>
<span class="line"><span>.cursor/skills/&lt;instance&gt;/autodevelop/.policies/</span></span>
<span class="line"><span>.cursor/skills/&lt;instance&gt;/autodevelop/.configuration/</span></span></code></pre></div><p>First day: <a href="./cli">sign in</a>, then <a href="./github">connect the GitHub App</a>. The pack may write Project and field ids into <code>config.json</code>. You can still fill the files by hand.</p><h2 id="config-json" tabindex="-1">config.json <a class="header-anchor" href="#config-json" aria-label="Permalink to &quot;config.json&quot;">​</a></h2><p>Required:</p><ul><li><code>github.owner</code>, <code>github.repo</code>, <code>github.projectNumber</code>, <code>github.projectId</code></li><li>Status field id and status option ids from the Project</li><li><code>mail.firestoreProject</code> and <code>mail.allowlist</code></li><li><code>forbiddenProjects</code> (production Firebase ids Autodevelop must never write)</li><li><code>preview.firebaseProject</code> and <code>preview.baseBranch</code> (usually <code>master</code>)</li><li><code>board.provider</code> — <code>github</code> is the shipped board</li></ul><p>Optional:</p><ul><li><code>docs.home</code> / <code>docs.changelog</code> — links used in release mail</li><li><code>firebase.staging</code> / <code>firebase.production</code> — environment checks</li><li><code>productName</code> / <code>stakeholderLabel</code> — labels in generated copy</li><li><code>singleBranch</code> — <code>true</code> when the repo has one shared branch</li><li><code>branches.staging</code> / <code>branches.production</code> — git branch names (defaults <code>master</code> / <code>release</code>)</li></ul><p>Mail today is Firestore Trigger Email on the consumer Firebase project. Do not put passwords in <code>config.json</code>.</p><h2 id="people-json" tabindex="-1">people.json <a class="header-anchor" href="#people-json" aria-label="Permalink to &quot;people.json&quot;">​</a></h2><ul><li><code>developers</code> — assignees (GitHub login and email)</li><li><code>stakeholders</code> — reviewers who receive ticket mail</li><li><code>alwaysNotify</code> or <code>alwaysNotifyEmails</code> — always on release digest and production-approval mail</li></ul><p>In chat you can add people who are not in the file: type <code>@login</code> and/or an email. The agent updates <code>people.json</code> after you confirm, then invites when you say <strong>invite</strong>.</p><h2 id="policies" tabindex="-1">Policies <a class="header-anchor" href="#policies" aria-label="Permalink to &quot;Policies&quot;">​</a></h2><p>Copy the kit example policy files into <code>.policies/</code>, dropping the <code>.example</code> suffix. A missing folder uses the kit defaults. Typical files:</p><table tabindex="0"><thead><tr><th>File</th><th>What it sets</th></tr></thead><tbody><tr><td><code>branch-policy.yaml</code></td><td>Staging and production branch names and ask flags</td></tr><tr><td><code>email-policy.yaml</code></td><td>Confirm required; allowlist lives in <code>config.json</code></td></tr><tr><td><code>security-policy.yaml</code></td><td>No env or admin JSON in git</td></tr><tr><td><code>ticket-policy.yaml</code></td><td>Ticket required for product work</td></tr><tr><td><code>commit-policy.yaml</code></td><td>Subject style; no force-push</td></tr><tr><td><code>environments-policy.yaml</code></td><td><code>staging</code>, <code>production</code>, <code>preview</code></td></tr></tbody></table><p>When <code>askStaging</code> or <code>askProduction</code> is true, the matching phrase is required before a push to that branch: <code>YES PUSH TO MASTER</code> or <code>YES PUSH TO RELEASE</code>.</p><p><code>pnpm autodevelop login</code> installs the organization’s versioned policy pack into the current repository. When the hosted pack version differs from the local version, the agent asks in chat before installing again.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./install">Install</a></li><li><a href="./cli">CLI</a></li><li><a href="./workflows/initial-setup">Initial setup</a></li><li><a href="./integration">Integration</a></li></ul>`,21)])])}const g=o(d,[["render",n]]);export{u as __pageData,g as default};
